package vn.edu.usth.hanoilens.shared;

import com.github.f4b6a3.uuid.UuidCreator;
import java.util.UUID;

/** Primary keys are UUIDv7 (time-ordered) generated by the application, never by the database. */
public final class Ids {

    private Ids() {
    }

    public static UUID newId() {
        return UuidCreator.getTimeOrderedEpoch();
    }

    /** Parses a path/query id; an unparsable id can never match a row, so it is a plain 404. */
    public static UUID parseOrNotFound(String raw) {
        try {
            return UUID.fromString(raw);
        } catch (IllegalArgumentException | NullPointerException ex) {
            throw ApiException.notFound("Resource not found.");
        }
    }
}
